  Lemma y32_join5 : forall q pt nb bits flag mm (xra x8 x9 a0 a7 x19 x21 t4 t6 : word),
    X4F' mm SPL BD -> 0 <= q <= Q2 -> 0 <= nb <= pt -> nb <= 8 -> pt - nb + 8 <= L2 -> 0 <= bits <= 64 ->
    (flag = 0 \/ flag = 1) ->
    (forall q' pt' bits' mm' (xra' x8' x9' a0' a1' a3' a7' x19' x21' t4' t6' : word),
       X4F' mm' SPL BD -> q < q' <= Q2 -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= L2) -> 0 <= bits' <= 64 ->
       evt psegs POST (HD5 0x1730c mm' q' pt' bits' xra' x8' x9' a0' a1' a3' a7' x19' x21' t4' t6')) ->
